mapper.update:
UPDATE agent_recall_eval_dataset SET name=#{name}, description=#{description}, status=#{status},
  corpus_count=#{corpusCount}, ready_corpus_count=#{readyCorpusCount}, case_count=#{caseCount},
  failure_code=#{failureCode}, failure_message=#{failureMessage}, updated_at=#{updatedAt}
WHERE dataset_id=#{datasetId}

mapper.select:
SELECT  FROM agent_recall_eval_corpus_item
WHERE dataset_id=#{datasetId}
AND status=#{status}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE agent_recall_eval_corpus_item SET title=#{title}, summary=#{summary}, content_ref=#{contentRef},
  tags_json=#{tagsJson}, source_type=#{sourceType}, source_id=#{sourceId}, parent_source_id=#{parentSourceId},
  source_refs_json=#{sourceRefsJson}, status=#{status}, failure_stage=#{failureStage},
  failure_code=#{failureCode}, failure_message=#{failureMessage}, updated_at=#{updatedAt}
WHERE corpus_item_id=#{corpusItemId}

mapper.select:
SELECT  FROM agent_recall_eval_case WHERE dataset_id=#{datasetId}
AND status=#{status}
ORDER BY created_at ASC, id ASC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE agent_recall_eval_case SET query_text=#{queryText}, source_scope=#{sourceScope},
  expected_json=#{expectedJson}, tags_json=#{tagsJson}, status=#{status}, updated_at=#{updatedAt}
WHERE case_id=#{caseId}

UPDATE agent_recall_eval_run SET name=#{name}, status=#{status}, config_json=#{configJson},
  metrics_json=#{metricsJson}, total_case_count=#{totalCaseCount}, completed_case_count=#{completedCaseCount},
  failed_case_count=#{failedCaseCount}, cancel_requested=#{cancelRequested}, failure_code=#{failureCode},
  failure_message=#{failureMessage}, started_at=#{startedAt}, completed_at=#{completedAt}, updated_at=#{updatedAt}
WHERE evaluation_run_id=#{evaluationRunId}
